describe('Unsaved Form Navigation Warning', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display warning when user attempts to navigate away from unsaved form', () => {
    // Fill in form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Verify form is unsaved
    cy.get('[data-testid="save-button"]').should('be.visible');
    cy.get('[data-testid="unsaved-indicator"]').should('contain', 'Unsaved');

    // Attempt to navigate away
    cy.get('[data-testid="nav-link-dashboard"]').click();

    // Verify warning modal appears
    cy.get('[data-testid="unsaved-warning-modal"]').should('be.visible');
    cy.get('[data-testid="warning-title"]').should('contain', 'Unsaved Changes');
    cy.get('[data-testid="warning-message"]').should('contain', 'You have unsaved changes');

    // Verify warning modal contains confirm and cancel buttons
    cy.get('[data-testid="warning-confirm-button"]').should('be.visible');
    cy.get('[data-testid="warning-cancel-button"]').should('be.visible');

    // User cancels navigation
    cy.get('[data-testid="warning-cancel-button"]').click();

    // Verify user remains on the form page
    cy.url().should('include', '/form');
    cy.get('[data-testid="unsaved-indicator"]').should('contain', 'Unsaved');
  });

  it('should allow navigation when form is saved', () => {
    // Fill in form fields
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a saved message');

    // Save the form
    cy.get('[data-testid="save-button"]').click();
    cy.get('[data-testid="save-success-message"]').should('be.visible');

    // Verify form is saved
    cy.get('[data-testid="unsaved-indicator"]').should('not.exist');

    // Attempt to navigate away
    cy.get('[data-testid="nav-link-dashboard"]').click();

    // Verify warning modal does NOT appear
    cy.get('[data-testid="unsaved-warning-modal"]').should('not.exist');

    // Verify user navigates to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });
});
